def inspect_offset(inputs):
    if 'offset' not in inputs:
        return {'accepted': False, 'offset': None}
    offset = inputs['offset']
    if offset is None:
        return {'accepted': False, 'offset': None}
    if type(offset) is bool or not type(offset) is int or not -4 <= offset <= 5:
        return {'accepted': False, 'offset': None}
    return {'accepted': True, 'offset': offset}
